arduino.setup:
Serial.begin(9600);
pinMode(${IN1}, OUTPUT);
pinMode(${IN2}, OUTPUT);
pinMode(${OUT}, INPUT);
Serial.println("AND Gate ready");

arduino.loop:
for (int i=0; i<4; i++) {
  digitalWrite(${IN1}, (i&1)?HIGH:LOW);
  digitalWrite(${IN2}, (i&2)?HIGH:LOW);
  delay(5);
  Serial.print("AND | ");
  Serial.print((i&1)?1:0);
  Serial.print((i&2)?1:0);
  Serial.print(" -> ");
  Serial.println(digitalRead(${OUT}));
  delay(500);
}
